function validate([boxes]) {
  if (typeof boxes !== 'string') return 'boxes must be a string.';
  if (boxes.length < 1 || boxes.length > 2000) return 'boxes needs 1 to 2000 characters.';
  if (!/^[01]+$/.test(boxes)) return "boxes may only contain '0' and '1'.";
  return null;
}

