function minOperations(boxes) {
  const n = boxes.length;
  const answer = new Array(n).fill(0);
  let balls = 0;
  let cost = 0;

  for (let i = 0; i < n; i++) {
    answer[i] = cost;
    if (boxes[i] === '1') {
      balls++;
    }
    cost += balls;
  }

  balls = 0;
  cost = 0;
  for (let i = n - 1; i >= 0; i--) {
    answer[i] += cost;
    if (boxes[i] === '1') {
      balls++;
    }
    cost += balls;
  }
  return answer;
}

