function minOperations(boxes) {
  const answer = [];
  for (let target = 0; target < boxes.length; target++) {
    let total = 0;
    for (let j = 0; j < boxes.length; j++) {
      if (boxes.charAt(j) === '1') total += Math.abs(target - j);
    }
    answer.push(total);
  }
  return answer;
}

