function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 10);
  const density = rand();
  let boxes = '';
  for (let i = 0; i < n; i++) boxes += rand() < density ? '1' : '0';
  return [boxes];
}
